import os, glob, json, re
from collections import Counter

# Sample worker sessions from different time periods
worker_files = []
for acc in [2,4,5]:
    d = f"/home/ubuntu/.claude-account-{acc}/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation"
    worker_files.extend(sorted(glob.glob(os.path.join(d, '*.jsonl'))))

# Group by tag in first user message — try to extract task type
task_types = Counter()
task_failures = Counter()
for f in worker_files[:100]:
    try:
        with open(f, errors='ignore') as fp:
            first_user = None
            for line in fp:
                try: d = json.loads(line)
                except: continue
                if d.get('type') == 'user':
                    msg = d.get('message',{})
                    content = msg.get('content','')
                    if isinstance(content, list):
                        content = ' '.join([c.get('text','') if isinstance(c,dict) else str(c) for c in content])
                    if first_user is None and len(content) > 100:
                        first_user = content[:3000]
                        # Try to extract task type
                        m = re.search(r'<task_type>([^<]+)</task_type>', content)
                        if m:
                            task_types[m.group(1).strip()] += 1
                        else:
                            # try first 100 chars task hints
                            if 'submit' in content[:500].lower() and 'training' in content[:1000].lower():
                                task_types['submit_training'] += 1
                            elif 'analyze' in content[:500].lower() or 'analysis' in content[:500].lower():
                                task_types['analyze'] += 1
                            elif 'eval' in content[:500].lower():
                                task_types['eval'] += 1
                            else:
                                task_types['unknown'] += 1
                        break
    except: pass
print('Task types (sample 100 sessions):')
for k, v in task_types.most_common(20):
    print(f"  {v:4d} {k}")
