import os, glob, json
files = sorted(glob.glob('/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation/*.jsonl'), key=os.path.getsize, reverse=True)
