for f in medium:
    print('====', os.path.basename(f), os.path.getsize(f), 'bytes')
    tools = []
    errors = []
    user_msg = None
    last_summary = None
    with open(f, errors='ignore') as fp:
        for line in fp:
            try: d = json.loads(line)
            except: continue
            if d.get('type') == 'assistant':
                msg = d.get('message',{})
                content = msg.get('content',[])
                if isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict):
                            if c.get('type') == 'tool_use':
                                tools.append(c.get('name'))
                            elif c.get('type') == 'text':
                                t = c.get('text','')
                                if t: last_summary = t[:300]
            elif d.get('type') == 'user' and user_msg is None:
                msg = d.get('message',{})
                content = msg.get('content','')
                if isinstance(content, list):
                    content = ' '.join([c.get('text','') if isinstance(c,dict) else str(c) for c in content])
                if len(content) > 200:
                    user_msg = content[:400]
            elif d.get('type') == 'user':
                msg = d.get('message',{})
                content = msg.get('content','')
                if isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict) and c.get('type') == 'tool_result' and c.get('is_error'):
                            errors.append(str(c.get('content',''))[:200])
    print('TOP USER:', (user_msg or '')[:300].replace('\n',' '))
    from collections import Counter
    cnt = Counter(tools)
    print('Tools:', dict(cnt.most_common(5)))
    print(f'Errors: {len(errors)}')
    for e in errors[:3]: print(' ERR:', e[:200])
    print('LAST SUMMARY:', (last_summary or '')[:300].replace('\n',' '))
    print()
